9	type responseEnvelope struct {
10		Type           string  `json:"type"`
11		Subtype        string  `json:"subtype"`
12		IsError        bool    `json:"is_error"`
13		APIErrorStatus *int    `json:"api_error_status"`
14		Result         *string `json:"result"`
15	}
