17	// parseGenerateTextResponse extracts the raw text payload and envelope metadata
18	// from Claude CLI JSON output. Claude may return either a single object or an array of events.
19	// The returned envelope allows callers to check IsError and APIErrorStatus.
20	func parseGenerateTextResponse(stdout []byte) (string, *responseEnvelope, error) {
21		var response responseEnvelope
22		if err := json.Unmarshal(stdout, &response); err == nil && response.Result != nil {
23			return *response.Result, &response, nil
24		}
25	
26		var responses []responseEnvelope
27		if err := json.Unmarshal(stdout, &responses); err != nil {
28			return "", nil, fmt.Errorf("unsupported Claude CLI JSON response: %w", err)
29		}
30	
31		for i := len(responses) - 1; i >= 0; i-- {
32			if responses[i].Type == "result" && responses[i].Result != nil {
33				return *responses[i].Result, &responses[i], nil
34			}
35		}
36	
37		return "", nil, errors.New("unsupported Claude CLI JSON response: missing result item")
38	}
