543	// formatCheckpointSummaryError maps typed Claude CLI errors and context
544	// sentinels to user-facing messages. This is the single point where the
545	// final CLI wording is decided.
546	func formatCheckpointSummaryError(err error, deadline time.Duration) error {
547		var claudeErr *claudecode.ClaudeError
548		switch {
549		case errors.As(err, &claudeErr):
550			switch claudeErr.Kind { //nolint:exhaustive // ClaudeErrorUnknown handled by default
551			case claudecode.ClaudeErrorAuth:
552				return fmt.Errorf("Claude authentication failed: %s\nRun `claude login` and retry", claudeErr.Message) //nolint:staticcheck // ST1005: capitalized because Claude is a proper noun
553			case claudecode.ClaudeErrorRateLimit:
554				return fmt.Errorf("Claude rejected the summary request due to rate limits or quota: %s\nWait and retry", claudeErr.Message) //nolint:staticcheck // ST1005
555			case claudecode.ClaudeErrorConfig:
556				return fmt.Errorf("Claude rejected the summary request: %s\nCheck your Claude CLI config and selected model", claudeErr.Message) //nolint:staticcheck // ST1005
557			case claudecode.ClaudeErrorCLIMissing:
558				return errors.New("Claude CLI is not installed or not on PATH") //nolint:staticcheck // ST1005
559			default:
560				return fmt.Errorf("Claude failed to generate the summary: %s", claudeErr.Message) //nolint:staticcheck // ST1005
561			}
562		case errors.Is(err, context.DeadlineExceeded):
563			return fmt.Errorf( //nolint:staticcheck // ST1005
564				"Claude did not return a summary within the %s safety deadline. This usually means one of:\n"+
565					"  - sonnet is taking longer than expected on a large transcript\n"+
566					"    Try: set summary_timeout_seconds: 600 in .entire/settings.local.json (or 0 to disable)\n"+
567					"  - the Claude CLI cannot reach Anthropic's API (network, VPN, firewall)\n"+
568					"    Try: run `claude --print \"hi\"` from a shell to confirm the CLI works\n"+
569					"  - Anthropic's API is degraded\n"+
570					"    Check: https://status.anthropic.com",
571				formatSummaryTimeout(deadline))
572		case errors.Is(err, context.Canceled):
573			return errors.New("summary generation canceled")
574		default:
575			return fmt.Errorf("failed to generate summary: %w", err)
576		}
577	}
