8	func TestParseGenerateTextResponse_IsErrorEnvelope(t *testing.T) {
9		t.Parallel()
10		stdout := `{"type":"result","subtype":"success","is_error":true,"api_error_status":404,"result":"model not found"}`
11		result, env, err := parseGenerateTextResponse([]byte(stdout))
12		if err != nil {
13			t.Fatalf("unexpected error: %v", err)
14		}
15		if result != "model not found" {
16			t.Errorf("result = %q; want %q", result, "model not found")
17		}
18		if env == nil {
19			t.Fatal("envelope = nil; want non-nil")
20		}
21		if !env.IsError {
22			t.Error("IsError = false; want true")
23		}
24		if env.APIErrorStatus == nil || *env.APIErrorStatus != 404 {
25			t.Errorf("APIErrorStatus = %v; want *404", env.APIErrorStatus)
26		}
