65	// Generator generates checkpoint summaries using an LLM.
66	type Generator interface {
67		// Generate creates a summary from checkpoint data.
68		// Returns the generated summary or an error if generation fails.
69		Generate(ctx context.Context, input Input) (*checkpoint.Summary, error)
70	}
71	
72	// Input contains condensed checkpoint data for summarization.
73	type Input struct {
74		// Transcript is the condensed transcript entries
75		Transcript []Entry
76	
77		// FilesTouched are the files modified during the session
78		FilesTouched []string
79	}
80	
81	// EntryType represents the type of a transcript entry.
82	type EntryType string
83	
84	const (
85		// EntryTypeUser indicates a user prompt entry.
86		EntryTypeUser EntryType = "user"
87		// EntryTypeAssistant indicates an assistant response entry.
88		EntryTypeAssistant EntryType = "assistant"
89		// EntryTypeTool indicates a tool call entry.
90		EntryTypeTool EntryType = "tool"
91	)
92	
93	// Entry represents one item in the condensed transcript.
94	type Entry struct {
95		// Type is the entry type (user, assistant, tool)
96		Type EntryType
97	
98		// Content is the text content for user/assistant entries
99		Content string
100	
101		// ToolName is the name of the tool (for tool entries)
102		ToolName string
103	
104		// ToolDetail is a description or file path (for tool entries)
105		ToolDetail string
106	}
