108	// minimalDetailTools lists tools that should show only essential details in summaries.
109	// These tools often have verbose outputs that don't add value to summarization.
110	// The detail shown is typically just a path, URL, or identifier rather than full content.
111	var minimalDetailTools = map[string]bool{
112		"Skill":    true, // Show skill name only, not loaded content
113		"Read":     true, // Show file path only, not file contents
114		"WebFetch": true, // Show URL only, not fetched content
115	}
