117	// BuildCondensedTranscriptFromBytes parses pre-redacted transcript bytes and extracts a condensed view.
118	// This is a convenience function that combines parsing and condensing.
119	// The agentType parameter determines which parser to use (Claude/OpenCode JSONL vs Gemini JSON).
120	func BuildCondensedTranscriptFromBytes(content redact.RedactedBytes, agentType types.AgentType) ([]Entry, error) {
121		switch agentType {
122		case agent.AgentTypeGemini:
123			return buildCondensedTranscriptFromGemini(content)
124		case agent.AgentTypeFactoryAIDroid:
125			return buildCondensedTranscriptFromDroid(content)
126		case agent.AgentTypeOpenCode:
127			return buildCondensedTranscriptFromOpenCode(content)
128		case agent.AgentTypeCodex:
129			return buildCondensedTranscriptFromCodex(content)
130		case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeUnknown:
131			// Claude/cursor format - fall through to shared logic below
132		}
133		// Claude format (JSONL) - handles Claude Code, Unknown, and any future agent types
134		lines, err := transcript.ParseFromBytes(content.Bytes())
135		if err != nil {
136			return nil, fmt.Errorf("failed to parse transcript: %w", err)
137		}
138		return BuildCondensedTranscript(lines), nil
139	}
