180	// buildCondensedTranscriptFromOpenCode parses OpenCode export JSON transcript and extracts a condensed view.
181	func buildCondensedTranscriptFromOpenCode(redacted redact.RedactedBytes) ([]Entry, error) {
182		session, err := opencode.ParseExportSession(redacted.Bytes())
183		if err != nil {
184			return nil, fmt.Errorf("failed to parse OpenCode transcript: %w", err)
185		}
186		if session == nil {
187			return nil, nil
188		}
189	
190		var entries []Entry
191		for _, msg := range session.Messages {
192			switch msg.Info.Role {
193			case "user":
194				text := opencode.ExtractTextFromParts(msg.Parts)
195				if text != "" {
196					entries = append(entries, Entry{
197						Type:    EntryTypeUser,
198						Content: text,
199					})
200				}
201			case "assistant":
202				text := opencode.ExtractTextFromParts(msg.Parts)
203				if text != "" {
204					entries = append(entries, Entry{
205						Type:    EntryTypeAssistant,
206						Content: text,
207					})
208				}
209				for _, part := range msg.Parts {
210					if part.Type == "tool" && part.State != nil {
211						entries = append(entries, Entry{
212							Type:       EntryTypeTool,
213							ToolName:   part.Tool,
214							ToolDetail: extractOpenCodeToolDetail(part.State.Input),
215						})
216					}
217				}
218			}
219		}
220	
221		return entries, nil
222	}
