224	// buildCondensedTranscriptFromCodex converts Codex rollout JSONL into the compact
225	// transcript format, then reuses the shared transcript condensation logic.
226	func buildCondensedTranscriptFromCodex(content redact.RedactedBytes) ([]Entry, error) {
227		compacted, err := compact.Compact(content, compact.MetadataFields{
228			Agent:      "codex",
229			CLIVersion: "summarize",
230		})
231		if err != nil {
232			return nil, fmt.Errorf("failed to compact Codex transcript: %w", err)
233		}
234	
235		type compactUserTextBlock struct {
236			Text string `json:"text"`
237		}
238		type compactAssistantBlock struct {
239			Type  string          `json:"type"`
240			Text  string          `json:"text,omitempty"`
241			Name  string          `json:"name,omitempty"`
242			Input json.RawMessage `json:"input,omitempty"`
243		}
244		type compactLine struct {
245			Type    string          `json:"type"`
246			Content json.RawMessage `json:"content"`
247		}
248	
249		var entries []Entry
250		for _, lineBytes := range splitCompactJSONL(compacted) {
251			var line compactLine
252			if err := json.Unmarshal(lineBytes, &line); err != nil {
253				continue
254			}
255	
256			switch line.Type {
257			case transcript.TypeUser:
258				var blocks []compactUserTextBlock
259				if err := json.Unmarshal(line.Content, &blocks); err != nil {
260					continue
261				}
262				for _, block := range blocks {
263					if block.Text != "" {
264						entries = append(entries, Entry{
265							Type:    EntryTypeUser,
266							Content: block.Text,
267						})
268					}
269				}
270			case transcript.TypeAssistant:
271				var blocks []compactAssistantBlock
272				if err := json.Unmarshal(line.Content, &blocks); err != nil {
273					continue
274				}
275				for _, block := range blocks {
276					switch block.Type {
277					case transcript.ContentTypeText:
278						if block.Text != "" {
279							entries = append(entries, Entry{
280								Type:    EntryTypeAssistant,
281								Content: block.Text,
282							})
283						}
284					case transcript.ContentTypeToolUse:
285						var input map[string]interface{}
286						if err := json.Unmarshal(block.Input, &input); err != nil {
287							input = nil
288						}
289						entries = append(entries, Entry{
290							Type:       EntryTypeTool,
291							ToolName:   block.Name,
292							ToolDetail: extractGenericToolDetail(input),
293						})
294					}
295				}
296			}
297		}
298	
299		return entries, nil
300	}
301	
302	// buildCondensedTranscriptFromDroid parses Droid transcript and extracts a condensed view.
303	func buildCondensedTranscriptFromDroid(redacted redact.RedactedBytes) ([]Entry, error) {
304		droidLines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes(redacted.Bytes(), 0)
305		if err != nil {
306			return nil, fmt.Errorf("failed to parse Droid transcript: %w", err)
307		}
308		return BuildCondensedTranscript(droidLines), nil
309	}
