311	// extractOpenCodeToolDetail extracts a detail string from an OpenCode tool's input map.
312	// OpenCode uses camelCase keys (e.g., "filePath" instead of "file_path").
313	func extractOpenCodeToolDetail(input map[string]interface{}) string {
314		for _, key := range []string{"description", "command", "filePath", "path", "pattern"} {
315			if v, ok := input[key].(string); ok && v != "" {
316				return v
317			}
318		}
319		return ""
320	}
321	
322	// extractGenericToolDetail extracts an appropriate detail string from a tool's input/args map.
323	// Checks common fields in order of preference. Used by Gemini condensation.
324	func extractGenericToolDetail(input map[string]interface{}) string {
325		if input == nil {
326			return ""
327		}
328		for _, key := range []string{"description", "command", "cmd", "file_path", "path", "pattern"} {
329			if v, ok := input[key].(string); ok && v != "" {
330				return v
331			}
332		}
333		return ""
334	}
