//go:build sim963

// Package cli — user-perspective simulation of PR 963 fixes.
// Run with: go test -tags=sim963 -v -run TestPR963UserSim ./cmd/entire/cli/
//
// This file is guarded by the "sim963" build tag so it never runs in normal
// test passes. It exists to render each Claude CLI failure mode the way an
// `entire explain --generate` user would see it, end-to-end:
//
//   stub claude CLI
//       -> claudecode.GenerateText (envelope / stderr classification)
//          -> summarize.ClaudeGenerator.Generate (//nolint:wrapcheck preservation)
//             -> summarize.GenerateFromTranscript (//nolint:wrapcheck preservation)
//                -> formatCheckpointSummaryError (user-facing wording)
//                   -> printed output
package cli

import (
	"context"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/summarize"
	"github.com/entireio/cli/redact"
)

// renderUserMessage runs the full error-surface path for one failure
// scenario and returns what the user would see on stderr for
// `entire explain --generate`.
func renderUserMessage(t *testing.T, agentBuilder func() *claudecode.ClaudeCodeAgent) string {
	t.Helper()

	agent := agentBuilder()
	gen := &summarize.ClaudeGenerator{TextGenerator: agent}

	transcript := []byte(`{"type":"user","message":{"content":"Hi"}}
{"type":"assistant","message":{"content":[{"type":"text","text":"Hello"}]}}`)

	// Short ctx deadline so sim runs don't hang even if a stub misbehaves.
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	_, err := summarize.GenerateFromTranscript(
		ctx,
		redact.AlreadyRedacted(transcript),
		nil,
		types.AgentType("claude-code"),
		gen,
	)
	if err == nil {
		return "<no error — generator returned summary>"
	}

	// 30s matches main's defaultCheckpointSummaryTimeout — used only to
	// format the deadline label in DeadlineExceeded branch.
	formatted := formatCheckpointSummaryError(err, 30*time.Second)
	return formatted.Error()
}

// stubRunner returns a CommandRunner that invokes /bin/sh with a script
// that prints `stdoutJSON` and exits with `exitCode`, optionally writing
// `stderr` first.
func stubRunner(stdoutJSON, stderr string, exitCode int) func(ctx context.Context, name string, arg ...string) *exec.Cmd {
	script := ""
	if stderr != "" {
		script += fmt.Sprintf("printf '%%s' %q 1>&2\n", stderr)
	}
	if stdoutJSON != "" {
		script += fmt.Sprintf("printf '%%s' %q\n", stdoutJSON)
	}
	script += fmt.Sprintf("exit %d\n", exitCode)

	return func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
		return exec.CommandContext(ctx, "/bin/sh", "-c", script)
	}
}

// missingRunner returns a runner that points at a guaranteed-absent binary
// to exercise the "cli missing" path.
func missingRunner() func(ctx context.Context, name string, arg ...string) *exec.Cmd {
	return func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
		return exec.CommandContext(ctx, "/definitely/not/a/real/binary/claude-xyz")
	}
}

type scenario struct {
	name    string
	purpose string
	build   func() *claudecode.ClaudeCodeAgent
}

func TestPR963UserSim(t *testing.T) {
	intStatus := func(n int) string { return fmt.Sprintf(`"api_error_status":%d,`, n) }

	scenarios := []scenario{
		{
			name:    "auth-401-envelope",
			purpose: "Claude returns envelope with api_error_status:401 at exit 0 (common auth failure).",
			build: func() *claudecode.ClaudeCodeAgent {
				env := `{"type":"result","subtype":"error","is_error":true,` + intStatus(401) +
					`"result":"Invalid API key · Please run /login"}`
				a := claudecode.NewClaudeCodeAgent()
				a.CommandRunner = stubRunner(env, "", 0)
				return a
			},
		},
		{
			name:    "rate-limit-429",
			purpose: "Claude returns envelope with api_error_status:429.",
			build: func() *claudecode.ClaudeCodeAgent {
				env := `{"type":"result","subtype":"error","is_error":true,` + intStatus(429) +
					`"result":"Rate limit reached. Please try again in 1 hour."}`
				a := claudecode.NewClaudeCodeAgent()
				a.CommandRunner = stubRunner(env, "", 0)
				return a
			},
		},
		{
			name:    "config-invalid-model",
			purpose: "Claude returns 404 for an invalid model name.",
			build: func() *claudecode.ClaudeCodeAgent {
				env := `{"type":"result","subtype":"error","is_error":true,` + intStatus(404) +
					`"result":"Model \"haiku-nonsense\" not found"}`
				a := claudecode.NewClaudeCodeAgent()
				a.CommandRunner = stubRunner(env, "", 0)
				return a
			},
		},
		{
			name:    "null-result-envelope-500",
			purpose: "FIX #8: envelope with result:null and api_error_status:500.",
			build: func() *claudecode.ClaudeCodeAgent {
				env := `{"type":"result","subtype":"error_during_execution","is_error":true,` + intStatus(500) +
					`"result":null}`
				a := claudecode.NewClaudeCodeAgent()
				a.CommandRunner = stubRunner(env, "", 0)
				return a
			},
		},
		{
			name:    "envelope-auth-no-status",
			purpose: "FIX #10: envelope with auth text but no api_error_status.",
			build: func() *claudecode.ClaudeCodeAgent {
				env := `{"type":"result","subtype":"error","is_error":true,` +
					`"result":"Invalid API key — please run /login"}`
				a := claudecode.NewClaudeCodeAgent()
				a.CommandRunner = stubRunner(env, "", 0)
				return a
			},
		},
		{
			name:    "stderr-auth-nonzero-exit",
			purpose: "Claude dies non-zero before producing envelope; stderr contains 'Invalid API key'.",
			build: func() *claudecode.ClaudeCodeAgent {
				a := claudecode.NewClaudeCodeAgent()
				a.CommandRunner = stubRunner("", "error: Invalid API key", 1)
				return a
			},
		},
		{
			name:    "stderr-empty-oom-137",
			purpose: "FIX #5: non-zero exit, empty stderr (OOM / SIGKILL). Error() now includes exit code.",
			build: func() *claudecode.ClaudeCodeAgent {
				a := claudecode.NewClaudeCodeAgent()
				a.CommandRunner = stubRunner("", "", 137)
				return a
			},
		},
		{
			name:    "cli-missing",
			purpose: "claude binary not on PATH.",
			build: func() *claudecode.ClaudeCodeAgent {
				a := claudecode.NewClaudeCodeAgent()
				a.CommandRunner = missingRunner()
				return a
			},
		},
		{
			name:    "deadline-exceeded",
			purpose: "Context deadline fires before Claude responds (user sees the 3-cause guidance).",
			build: func() *claudecode.ClaudeCodeAgent {
				// Runner that sleeps forever so the outer ctx fires.
				runner := func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
					return exec.CommandContext(ctx, "/bin/sh", "-c", "sleep 60")
				}
				a := claudecode.NewClaudeCodeAgent()
				a.CommandRunner = runner
				return a
			},
		},
	}

	// Print a big human-readable report so the dev running this sees exactly
	// what a user would see for each failure mode.
	out := os.Stdout
	fmt.Fprintln(out, strings.Repeat("═", 78))
	fmt.Fprintln(out, "  PR 963 user-perspective simulation")
	fmt.Fprintln(out, "  Each block shows the rendered error a user of `entire explain --generate` sees.")
	fmt.Fprintln(out, strings.Repeat("═", 78))

	for _, sc := range scenarios {
		t.Run(sc.name, func(t *testing.T) {
			// deadline-exceeded must be sequential-ish — sleep + short deadline
			if sc.name != "deadline-exceeded" {
				t.Parallel()
			}

			// For deadline-exceeded, give the whole call just 500ms so sleep 60 races the ctx.
			msg := renderWithDeadline(t, sc.build, sc.name)

			header := fmt.Sprintf("  SCENARIO: %s", sc.name)
			fmt.Fprintln(out, "")
			fmt.Fprintln(out, strings.Repeat("─", 78))
			fmt.Fprintln(out, header)
			fmt.Fprintln(out, "  why:     "+sc.purpose)
			fmt.Fprintln(out, strings.Repeat("─", 78))
			for _, line := range strings.Split(msg, "\n") {
				fmt.Fprintln(out, "  | "+line)
			}
		})
	}
}

func renderWithDeadline(t *testing.T, build func() *claudecode.ClaudeCodeAgent, name string) string {
	t.Helper()

	// Give non-timeout scenarios a generous ceiling; tight one for the
	// deadline scenario to actually fire.
	ceiling := 5 * time.Second
	if name == "deadline-exceeded" {
		ceiling = 500 * time.Millisecond
	}

	agent := build()
	gen := &summarize.ClaudeGenerator{TextGenerator: agent}
	transcript := []byte(`{"type":"user","message":{"content":"Hi"}}
{"type":"assistant","message":{"content":[{"type":"text","text":"Hello"}]}}`)

	ctx, cancel := context.WithTimeout(context.Background(), ceiling)
	defer cancel()

	_, err := summarize.GenerateFromTranscript(
		ctx,
		redact.AlreadyRedacted(transcript),
		nil,
		types.AgentType("claude-code"),
		gen,
	)
	if err == nil {
		return "<no error — generator unexpectedly succeeded>"
	}
	return formatCheckpointSummaryError(err, ceiling).Error()
}

